import type { InputHTMLAttributes } from 'react';

export interface TextFieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  helpText?: string;
  error?: string;
}

export function TextField({
  className,
  error,
  helpText,
  id,
  label,
  required,
  ...inputProps
}: TextFieldProps) {
  const inputId = id ?? inputProps.name;

  if (!inputId) {
    throw new Error(
      'TextField requires an id or name so its label can be associated with the input.',
    );
  }

  const helpId = helpText ? `${inputId}-help` : undefined;
  const errorId = error ? `${inputId}-error` : undefined;
  const describedBy =
    [inputProps['aria-describedby'], helpId, errorId].filter(Boolean).join(' ') || undefined;

  return (
    <div className="ui-field">
      <label htmlFor={inputId}>
        {label}
        {required ? <span aria-hidden="true"> *</span> : null}
        {required ? <span className="sr-only"> (required)</span> : null}
      </label>
      <input
        {...inputProps}
        aria-describedby={describedBy}
        aria-invalid={error ? true : inputProps['aria-invalid']}
        className={['ui-field__input', className].filter(Boolean).join(' ')}
        id={inputId}
        required={required}
      />
      {helpText ? (
        <p className="ui-field__help" id={helpId}>
          {helpText}
        </p>
      ) : null}
      {error ? (
        <p className="ui-field__error" id={errorId}>
          {error}
        </p>
      ) : null}
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';

type PublicDataState<Data> =
  | { status: 'loading'; data: null; error: null }
  | { status: 'ready'; data: Data; error: null }
  | { status: 'error'; data: null; error: Error };

export function usePublicData<Data>(
  load: (signal: AbortSignal) => Promise<Data>,
  requestKey: string,
) {
  const [reloadCount, setReloadCount] = useState(0);
  const [state, setState] = useState<PublicDataState<Data>>({
    status: 'loading',
    data: null,
    error: null,
  });

  useEffect(() => {
    const controller = new AbortController();
    setState({ status: 'loading', data: null, error: null });

    void load(controller.signal)
      .then((data) => {
        if (!controller.signal.aborted) {
          setState({ status: 'ready', data, error: null });
        }
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setState({
            status: 'error',
            data: null,
            error: error instanceof Error ? error : new Error('The public API request failed.'),
          });
        }
      });

    return () => controller.abort();
  }, [load, reloadCount, requestKey]);

  const reload = useCallback(() => setReloadCount((count) => count + 1), []);

  return { ...state, reload };
}

