            participants={participants}
            value={event.strikerId}
          />
          <ParticipantSelect
            disabled={disabled}
            error={fieldErrors.nonStrikerId ?? ''}
            id="correction-non-striker"
            label="Non-striker"
            onChange={(participantId) => update('nonStrikerId', participantId)}
            participants={participants}
            value={event.nonStrikerId}
